import hashlib
import hmac
import os
import time
import json
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET_KEY = os.urandom(32)
SESSION_STORE = {}
STORE_LOCK = threading.Lock()

# Authorization cache to reduce DB lookups
AUTH_CACHE = {}
CACHE_LOCK = threading.Lock()
CACHE_TTL = 300  # 5 minutes

USERS = {
    'alice': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'alice_pass', b'salt_alice_1', 200000).hex(), 'salt': 'salt_alice_1', 'role': 'admin', 'department': 'engineering'},
    'bob': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'bob_pass', b'salt_bob_2', 200000).hex(), 'salt': 'salt_bob_2', 'role': 'user', 'department': 'sales'},
    'carol': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'carol_pass', b'salt_carol_3', 200000).hex(), 'salt': 'salt_carol_3', 'role': 'user', 'department': 'engineering'},
    'dave': {'password_hash': hashlib.pbkdf2_hmac('sha256', b'dave_pass', b'salt_dave_4', 200000).hex(), 'salt': 'salt_dave_4', 'role': 'manager', 'department': 'sales'},
}

RESOURCES = {
    'engineering_docs': {'allowed_roles': ['admin', 'manager'], 'allowed_departments': ['engineering']},
    'sales_reports': {'allowed_roles': ['admin', 'manager'], 'allowed_departments': ['sales']},
    'admin_panel': {'allowed_roles': ['admin'], 'allowed_departments': None},
    'company_wiki': {'allowed_roles': ['admin', 'manager', 'user'], 'allowed_departments': None},
}

ALLOWED_USERNAMES = set(USERS.keys())
ALLOWED_RESOURCES = set(RESOURCES.keys())
ALLOWED_ACTIONS = frozenset(('read', 'write', 'delete'))

def verify_password(username, password):
    if username not in USERS:
        hashlib.pbkdf2_hmac('sha256', password.encode(), b'dummy_salt', 200000)
        return False
    user = USERS[username]
    computed = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'].encode(), 200000).hex()
    return hmac.compare_digest(computed, user['password_hash'])

def create_session(username):
    session_id = hmac.new(SECRET_KEY, os.urandom(32), 'sha256').hexdigest()
    session_data = {
        'username': username,
        'role': USERS[username]['role'],
        'department': USERS[username]['department'],
        'created_at': time.time(),
    }
    with STORE_LOCK:
        SESSION_STORE[session_id] = session_data
    return session_id

def validate_session(session_id):
    if not isinstance(session_id, str) or len(session_id) != 64:
        return None
    with STORE_LOCK:
        session = SESSION_STORE.get(session_id)
    if session is None:
        return None
    if time.time() - session['created_at'] > 3600:
        with STORE_LOCK:
            SESSION_STORE.pop(session_id, None)
        return None
    return session

def build_cache_key(username, resource, action):
    """Build a cache key for authorization decisions using HMAC to prevent collisions."""
    key_material = json.dumps([username, resource, action], separators=(',', ':')).encode()
    return hmac.new(SECRET_KEY, key_material, 'sha256').hexdigest()

def check_authorization_cached(username, role, department, resource, action):
    """Check if user is authorized to perform action on resource, with caching."""
    # Validate inputs against known-good values
    if username not in ALLOWED_USERNAMES:
        return False
    if resource not in ALLOWED_RESOURCES:
        return False
    if action not in ALLOWED_ACTIONS:
        return False

    cache_key = build_cache_key(username, resource, action)

    with CACHE_LOCK:
        if cache_key in AUTH_CACHE:
            entry = AUTH_CACHE[cache_key]
            if time.time() - entry['timestamp'] < CACHE_TTL:
                return entry['allowed']
            else:
                del AUTH_CACHE[cache_key]

    # Perform actual authorization check
    allowed = check_authorization(role, department, resource)

    with CACHE_LOCK:
        AUTH_CACHE[cache_key] = {'allowed': allowed, 'timestamp': time.time()}

    return allowed

def check_authorization(role, department, resource):
    """Core authorization logic - checks role and department against resource policy."""
    if resource not in RESOURCES:
        return False
    policy = RESOURCES[resource]

    # Check role
    if role not in policy['allowed_roles']:
        return False

    # Check department (None means any department is allowed)
    if policy['allowed_departments'] is not None:
        if department not in policy['allowed_departments']:
            return False

    return True

def get_session_from_cookie(headers):
    cookie_header = headers.get('Cookie', '')
    for part in cookie_header.split(';'):
        part = part.strip()
        if part.startswith('session_id='):
            return part[len('session_id='):]
    return None

class RequestHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass  # Suppress logs

    def send_json(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def read_body(self):
        length = int(self.headers.get('Content-Length', 0))
        if length > 4096:
            return None
        return self.rfile.read(length)

    def do_POST(self):
        if self.path == '/login':
            self.handle_login()
        elif self.path == '/logout':
            self.handle_logout()
        else:
            self.send_json(404, {'error': 'not found'})

    def do_GET(self):
        if self.path.startswith('/resource/'):
            self.handle_resource_access()
        elif self.path == '/profile':
            self.handle_profile()
        else:
            self.send_json(404, {'error': 'not found'})

    def handle_login(self):
        body = self.read_body()
        if not body:
            self.send_json(400, {'error': 'invalid request'})
            return
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self.send_json(400, {'error': 'invalid json'})
            return
        username = data.get('username', '')
        password = data.get('password', '')
        if not isinstance(username, str) or not isinstance(password, str):
            self.send_json(400, {'error': 'invalid types'})
            return
        if len(username) > 64 or len(password) > 128:
            self.send_json(400, {'error': 'input too long'})
            return
        if not verify_password(username, password):
            self.send_json(401, {'error': 'invalid credentials'})
            return
        session_id = create_session(username)
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Set-Cookie', f'session_id={session_id}; HttpOnly; Secure; SameSite=Strict')
        body_out = json.dumps({'status': 'ok', 'username': username}).encode()
        self.send_header('Content-Length', str(len(body_out)))
        self.end_headers()
        self.wfile.write(body_out)

    def handle_logout(self):
        session_id = get_session_from_cookie(self.headers)
        if session_id:
            with STORE_LOCK:
                SESSION_STORE.pop(session_id, None)
        self.send_json(200, {'status': 'logged out'})

    def handle_profile(self):
        session_id = get_session_from_cookie(self.headers)
        session = validate_session(session_id)
        if not session:
            self.send_json(401, {'error': 'unauthorized'})
            return
        self.send_json(200, {
            'username': session['username'],
            'role': session['role'],
            'department': session['department']
        })

    def handle_resource_access(self):
        session_id = get_session_from_cookie(self.headers)
        session = validate_session(session_id)
        if not session:
            self.send_json(401, {'error': 'unauthorized'})
            return

        # Parse resource and action from path: /resource/{name}?action={action}
        path_parts = self.path.split('?')
        resource_path = path_parts[0]  # /resource/{name}
        resource_name = resource_path[len('/resource/'):]

        # Parse query string for action
        action = 'read'  # default action
        if len(path_parts) > 1:
            query = path_parts[1]
            for param in query.split('&'):
                if param.startswith('action='):
                    action = param[len('action='):]

        if not resource_name or len(resource_name) > 64:
            self.send_json(400, {'error': 'invalid resource'})
            return
        if action not in ALLOWED_ACTIONS:
            self.send_json(400, {'error': 'invalid action'})
            return

        username = session['username']
        role = session['role']
        department = session['department']

        allowed = check_authorization_cached(username, role, department, resource_name, action)

        if not allowed:
            self.send_json(403, {'error': 'forbidden'})
            return

        self.send_json(200, {'resource': resource_name, 'action': action, 'status': 'granted'})

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    server.serve_forever()
